  3932	static void expand_tabs(hoedown_buffer *ob, const uint8_t *line, size_t size)
  3933	{
  3934	        /* This code makes two assumptions:
  3935	         * - Input is valid UTF-8.  (Any byte with top two bits 10 is skipped,
  3936	         *   whether or not it is a valid UTF-8 continuation byte.)
  3937	         * - Input contains no combining characters.  (Combining characters
  3938	         *   should be skipped but are not.)
  3939	         */
  3940	        size_t  i = 0, tab = 0;
  3941	
  3942	        while (i < size) {
  3943	                size_t org = i;
  3944	
  3945	                while (i < size && line[i] != '\t') {
  3946	                        /* ignore UTF-8 continuation bytes */
  3947	                        if ((line[i] & 0xc0) != 0x80)
  3948	                                tab++;
  3949	                        i++;
  3950	                }
  3951	
  3952	                if (i > org)
  3953	                        hoedown_buffer_put(ob, line + org, i - org);
  3954	
  3955	                if (i >= size)
  3956	                        break;
  3957	
  3958	                do {
  3959	                        hoedown_buffer_putc(ob, ' '); tab++;
  3960	                } while (tab % 4);
